        new_row = []
        for c in range(cols):
            cell = grid[r][c]
            if cell != D:
                # Minority colors stay unchanged
                new_row.append(cell)
            else:
                # Dominant color at grid edge: keep as D
                if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                    new_row.append(D)
                else:
                    # Interior: check if any minority within Manhattan distance 1
                    convert = False
                    for nr in [r-1, r+1, r]:
                        for nc in [c-1, c+1, c]:
                            if (r != nr or c != nc):  # exclude self
                                if 0 <= nr < rows and 0 <= nc < cols:
                                    if grid[nr][nc] != D:
                                        convert = True
                                        break
                            if convert:
                                break
                    # Also check distance 1 diagonally
                    if not convert:
                        for nr in [r-1, r+1]:
                            for nc in [c-1, c+1]:
